import hashlib,importlib.util,json
from pathlib import Path
w=Path(__file__).parent;p=w/'book/manifest.json';s=w/'book/en/short_content.html'
spec=importlib.util.spec_from_file_location('build_books','tools/build_books.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
phrases='''proof of work|store of value|global currency|central gatekeeper|financial crisis|independent nodes|lightning network|fixed supply|censorship-resistant alternative|autonomy through decentralization|digital gold|greater financial sovereignty|public blockchain|centralized institutions|everyday global currency|central-bank decisions|electronic cash system|groups of transactions|inflation and economic instability|direct value transfer|electronic cash|usefulness for everyday payments|limited coin supply|medium of exchange|low-cost payments|new issuance|institutional adoption|third-party risk|financial sovereignty|independent computers|proof of stake|consensus mechanisms|cryptographic puzzle|decentralized ledger|economic instability|environmental debate|environmental costs|regulatory scrutiny|traditional banking|distributed ledger|financial autonomy|payment processors|central authority|everyday payments|investors seeking|practical future|price volatility|satoshi nakamoto|technical limits|transaction fees|wallet addresses|currency supply|fiat currencies|public identity|slow processing|public records|value transfer|shared ledger|mining power|public trust|valid block|periodic halving|supply cap|peer-to-peer electronic cash system|high fees|miners|nodes|block|pseudonymous|scarcity|censorship|manipulation|regulation|scalability|renewable energy|transactions|blockchain|transaction|payments|intermediary|verification|coin|energy use|environmental costs|digital finance|daily medium of exchange|mining energy|institutional adoption|financial institutions|direct payments'''.split('|')
phrases=[x for x in phrases if x not in {'satoshi nakamoto','energy use','digital finance','mining energy','financial institutions','direct payments'}]
phrases=list(dict.fromkeys(phrases))+['global financial crisis','blockchain records transactions','verification among many participants','newly issued bitcoins','fully anonymous','small payments','energy','central intermediary']
phrases=[{'small payments':'quick','central intermediary':'blockchain records'}.get(x,x) for x in phrases]
text=m.keyword_normalise(m.keyword_source_text(s));missing=[x for x in phrases if m.keyword_normalise(x) not in text]
print('count',len(phrases),'distinct',len(set(phrases)),'missing',missing,'duplicates',[x for x in phrases if phrases.count(x)>1])
if missing or len(phrases)!=90 or len(set(phrases))!=90:raise SystemExit(1)
d=json.loads(p.read_text());d['keywordReview']={'sourceHash':hashlib.sha256(s.read_bytes()).hexdigest(),'phrases':phrases,'status':'reviewed-source-grounded'};p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
